const trustedAgentIds = new WeakMap();
const weakMapGet = WeakMap.prototype.get;
const weakMapSet = WeakMap.prototype.set;
const apply = Reflect.apply;
/** @internal Bind a local eval transport to the exact agent it already resolved. */
export function bindTrustedLocalEvalFetch(requestFetch, agentId) {
    apply(weakMapSet, trustedAgentIds, [requestFetch, agentId]);
    return requestFetch;
}
/** @internal Read the server-established agent binding for a local eval transport. */
export function trustedLocalEvalFetchAgentId(requestFetch) {
    return requestFetch
        ? apply(weakMapGet, trustedAgentIds, [requestFetch])
        : undefined;
}
